async function onTaskUpdate(expression, task) {
  // IFC's 22-character GlobalId: 128 bits in base 64, with its own alphabet.
const IFC_GUID_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_$";
const compressUuid = (uuid) => {
  let value = BigInt("0x" + uuid.replace(/-/g, ""));
  let compressed = "";
  for (let i = 0; i < 22; i++) {
    compressed = IFC_GUID_ALPHABET[Number(value & 63n)] + compressed;
    value >>= 6n;
  }
  return compressed;
};

  const GLOBAL_ID = "0017204f-7897-5f00-82b6-104f8d4ec750";
  const LOCATIONS = "0c032743-7eac-5885-b39f-ecc41deb7084";
  const LOCATION_NAMES = "d9b7c6ab-5eed-5892-aa99-a40c8ddd3abc";
  const NAME = "d6632c72-89fa-4210-9d01-18e911505608";

  const id = await expression.getAttrByInstanceUUID(task.uuid, GLOBAL_ID);
  if (id && !id.value) {
    id.value = compressUuid(task.uuid);
    await expression.checkForVisualizationUpdateByAttributeUUID(task.uuid, GLOBAL_ID);
  }

  // A cell edit cannot redraw its task, so the card draws this copy of the table instead.
  // The reference is read through, so renaming a product reaches the card too, and the
  // name saved in the cell stands in while the product's scene is not loaded.
  const table = await expression.getAttrByInstanceUUID(task.uuid, LOCATIONS);
  const names = [];
  for (const cell of [...(table?.table_attributes ?? [])].sort((a, b) => a.table_row - b.table_row)) {
    const target = cell.role_instance_from?.uuid_has_reference_class_instance;
    if (target) names.push((await expression.attrvalByInst(NAME, target)) ?? cell.value);
  }
  const mirror = await expression.getAttrByInstanceUUID(task.uuid, LOCATION_NAMES);
  const value = names.join("\n");
  if (mirror && value !== (mirror.value ?? "")) {
    mirror.value = value;
    await expression.checkForVisualizationUpdateByAttributeUUID(task.uuid, LOCATION_NAMES);
  }
}

