async function checkSatisfiability(expression) {
  /**
 * Graph core of the Construction Flow procedures.
 *
 * A pure module: it receives a plain model and never touches the expression API, so the
 * algorithms can be tested without a client. The generator inlines this file into every
 * procedure string, which is why it is one factory function rather than an ES module.
 *
 * Sources, referred to by the same tags as the README:
 *   [C] Marengo, Nutt, Perktold: CoPModL. Information Systems 103 (2022).
 *   [T] Perktold: Processes in Construction: Modeling and Consistency Checking. MSc
 *       thesis, Free University of Bozen-Bolzano, 2017.
 *   [E] The EMMSAD 2026 paper this language comes from.
 *
 * Vocabulary follows [C]. A task is an activity on a set of items. An activity-item node
 * is one activity on one item, and is what start and end events belong to.
 *
 * Model shape:
 *   tasks:        { id, name, duration, workers, actor, ordering, exclusive, items[],
 *                   danglingLocations }
 *   items:        { [id]: { id, name, path[], zones: { [level]: zoneId }, elevation } }
 *   dependencies: { kind: "precedence" | "alternate" | "chain", from, to, scope }
 *   executions:   { from, to }
 *
 * `zones` is the projection Πs of [C] Definition 1: an item's value at each scope. `path`
 * is the item followed by everything that contains it. `scope`, `exclusive` and
 * `ordering` use the value "None" for absent, and `ordering` is otherwise "<" or ">".
 */
function createCopmodlCore() {
  /** Tolerance for comparing times, which are fractions of a day (Duration / n). */
  const EPSILON = 1e-9;
  /** Satisfiability is exponential in the worst case ([C] Section 5.4). */
  const DEFAULT_BUDGET_MS = 10000;
  /** Reversals tried while shortening a schedule, so a large model stays responsive. */
  const MAX_REVERSAL_TRIES = 400;

  // ---------------------------------------------------------------------------------
  // Graph construction: [C] Section 5.2 and [T] Sections 5.2, 5.3
  // ---------------------------------------------------------------------------------

  /**
   * Builds the disjunctive graph of a model. `arcs` are end-to-start precedences. An
   * entry of `edges` is a disjunctive edge between two node sets, meaning all of one set
   * finishes before any of the other starts ([T] Section 5.3.2 generalises [C]'s
   * group-to-node edge to this form).
   *
   * `execution` adds Execution relations, which are not constraints of the language.
   * `scheduleEdges` adds what only a schedule needs; see addScheduleEdges.
   */
  function buildGraph(model, options = {}) {
    const nodes = [];
    const nodeByKey = new Map();
    const nodesOfTask = new Map();

    // Keyed on activity and item, not task: two tasks of one activity sharing an item
    // yield a single node ([T] Section 5.1.1), because an activity runs once per item.
    for (const task of model.tasks) {
      const items = [...new Set(task.items)];
      const own = [];
      for (const item of items) {
        const key = `${task.name}\u0000${item}`;
        let node = nodeByKey.get(key);
        if (!node) {
          node = { index: nodes.length, activity: task.name, item, tasks: [], duration: 0 };
          nodes.push(node);
          nodeByKey.set(key, node);
        }
        node.tasks.push(task.id);
        node.duration = Math.max(node.duration, nodeDuration(task, items.length));
        own.push(node.index);
      }
      nodesOfTask.set(task.id, own);
    }

    const arcKeys = new Set();
    const arcs = [];
    const edges = [];
    const addArc = (from, to) => {
      const key = from * nodes.length + to;
      if (arcKeys.has(key)) return;
      arcKeys.add(key);
      arcs.push([from, to]);
    };
    const addArcs = (from, to) => {
      for (const u of from) for (const v of to) addArc(u, v);
    };

    const zoneOf = (index, scope) =>
      scope === "None" ? "*" : model.items[nodes[index].item]?.zones[scope];

    /** The selector σπ of [C]: nodes grouped by their zone at a scope. */
    const inZones = (indices, scope) => {
      const groups = new Map();
      for (const index of indices) {
        const zone = zoneOf(index, scope);
        if (zone === undefined) continue;
        if (!groups.has(zone)) groups.set(zone, []);
        groups.get(zone).push(index);
      }
      return groups;
    };
    const everyNode = nodes.map((node) => node.index);

    /** [C] precedence: for each zone in Πs(Ia) ∩ Πs(Ib), a finishes there before b starts. */
    const addPrecedence = (from, to, scope) => {
      const fromZones = inZones(nodesOfTask.get(from) ?? [], scope);
      const toZones = inZones(nodesOfTask.get(to) ?? [], scope);
      const shared = [];
      for (const [zone, fromNodes] of fromZones) {
        const toNodes = toZones.get(zone);
        if (!toNodes) continue;
        addArcs(fromNodes, toNodes);
        shared.push({ zone, members: [...new Set([...fromNodes, ...toNodes])] });
      }
      return shared;
    };

    /** A group against every other node in its zone: exclusive execution and chain. */
    const addGroupAgainstZone = (group, zone, scope, origin) => {
      const others = inZones(everyNode, scope).get(zone) ?? [];
      const inGroup = new Set(group);
      for (const other of others) {
        if (!inGroup.has(other)) edges.push({ x: group, y: [other], origin });
      }
    };

    for (const task of model.tasks) {
      // ordered_execution, partitioned by level regardless of sector ([C] Section 3.3).
      if (task.ordering === "<" || task.ordering === ">") {
        const groups = new Map();
        for (const index of nodesOfTask.get(task.id)) {
          const elevation = model.items[nodes[index].item]?.elevation;
          if (elevation === null || elevation === undefined) continue;
          if (!groups.has(elevation)) groups.set(elevation, []);
          groups.get(elevation).push(index);
        }
        const ascending = [...groups.keys()].sort((a, b) => a - b);
        const sequence = task.ordering === "<" ? ascending : ascending.reverse();
        for (let i = 0; i + 1 < sequence.length; i++) {
          addArcs(groups.get(sequence[i]), groups.get(sequence[i + 1]));
        }
      }

      // exclusive_execution. "None" leaves the default of [C], handled in addScheduleEdges.
      if (task.exclusive && task.exclusive !== "None") {
        const origin = { kind: "exclusive", task: task.id };
        for (const [zone, group] of inZones(nodesOfTask.get(task.id), task.exclusive)) {
          addGroupAgainstZone(group, zone, task.exclusive, origin);
        }
      }
    }

    for (const dependency of model.dependencies) {
      const shared = addPrecedence(dependency.from, dependency.to, dependency.scope);
      const origin = { kind: dependency.kind, from: dependency.from, to: dependency.to };
      if (dependency.kind === "alternate") {
        for (let i = 0; i < shared.length; i++) {
          for (let j = i + 1; j < shared.length; j++) {
            edges.push({ x: shared[i].members, y: shared[j].members, origin });
          }
        }
      } else if (dependency.kind === "chain") {
        for (const { zone, members } of shared) {
          addGroupAgainstZone(members, zone, dependency.scope, origin);
        }
      }
    }

    if (options.execution) {
      for (const execution of model.executions) {
        addArcs(nodesOfTask.get(execution.from) ?? [], nodesOfTask.get(execution.to) ?? []);
      }
    }

    const graph = { nodes, arcs, edges, nodesOfTask };
    if (options.scheduleEdges) addScheduleEdges(graph, model);
    return graph;
  }

  /**
   * A task's Duration is its total ([T] p. 16 and p. 61). [T] p. 58 derives a node's
   * duration from the pitch, the units performed per working day, without printing a
   * formula; with equal units that pitch is n / Duration, so a node takes Duration / n.
   */
  function nodeDuration(task, itemCount) {
    return task.duration > 0 && itemCount > 0 ? task.duration / itemCount : 0;
  }

  /**
   * Two kinds of simple edge a schedule must respect but satisfiability can ignore,
   * because a simple edge can always be oriented ([C] Lemma 8, [T] p. 58).
   *
   * Default exclusiveness: [C] forbids two tasks on one item at once, and [T] Section 6.1
   * extends that to items sharing a location, so a task on a storey also blocks work on a
   * wall inside it. One crew: a task works in one location at a time. That is our
   * assumption, since [E] Fig. 2 has no crew count, and it is what makes a task take its
   * full Duration.
   */
  function addScheduleEdges(graph, model) {
    const { nodes, edges } = graph;
    const pathOf = (node) => model.items[node.item]?.path ?? [node.item];
    for (let u = 0; u < nodes.length; u++) {
      for (let v = u + 1; v < nodes.length; v++) {
        const sameTask = nodes[u].tasks.some((task) => nodes[v].tasks.includes(task));
        const overlapping =
          pathOf(nodes[u]).includes(nodes[v].item) || pathOf(nodes[v]).includes(nodes[u].item);
        if (sameTask) edges.push({ x: [u], y: [v], origin: { kind: "crew" } });
        else if (overlapping) edges.push({ x: [u], y: [v], origin: { kind: "default-exclusive" } });
      }
    }
  }

  // ---------------------------------------------------------------------------------
  // Satisfiability: Sat and NDSat of [C] Section 5.3
  // ---------------------------------------------------------------------------------

  /** A subproblem: nodes renumbered densely, so reachability can use bitsets. */
  function makeProblem(ids, arcs, edges) {
    const position = new Map(ids.map((id, index) => [id, index]));
    const successors = ids.map(() => new Set());
    for (const [from, to] of arcs) {
      successors[position.get(from)].add(position.get(to));
    }
    return { ids, position, successors, edges };
  }

  function copyProblem(problem, edges) {
    return {
      ids: problem.ids,
      position: problem.position,
      successors: problem.successors.map((set) => new Set(set)),
      edges,
    };
  }

  function arcsOf(problem) {
    const arcs = [];
    problem.successors.forEach((set, from) => {
      for (const to of set) arcs.push([problem.ids[from], problem.ids[to]]);
    });
    return arcs;
  }

  function orient(problem, edge, direction) {
    const [from, to] = direction > 0 ? [edge.x, edge.y] : [edge.y, edge.x];
    for (const u of from) {
      const set = problem.successors[problem.position.get(u)];
      for (const v of to) set.add(problem.position.get(v));
    }
  }

  /** Kahn's algorithm. Returns undefined when the arcs contain a cycle. */
  function topologicalOrder(successors) {
    const indegree = new Array(successors.length).fill(0);
    for (const set of successors) for (const to of set) indegree[to]++;
    const queue = [];
    indegree.forEach((degree, node) => {
      if (degree === 0) queue.push(node);
    });
    const order = [];
    while (queue.length > 0) {
      const node = queue.pop();
      order.push(node);
      for (const to of successors[node]) {
        indegree[to]--;
        if (indegree[to] === 0) queue.push(to);
      }
    }
    return order.length === successors.length ? order : undefined;
  }

  /** One cycle of the arcs, as node ids, to show the user what cannot be executed. */
  function findCycle(problem) {
    const state = new Array(problem.successors.length).fill(0);
    const stack = [];
    const visit = (node) => {
      state[node] = 1;
      stack.push(node);
      for (const to of problem.successors[node]) {
        if (state[to] === 1) return stack.slice(stack.indexOf(to));
        if (state[to] === 0) {
          const cycle = visit(to);
          if (cycle) return cycle;
        }
      }
      state[node] = 2;
      stack.pop();
      return undefined;
    };
    for (let node = 0; node < state.length; node++) {
      if (state[node] === 0) {
        const cycle = visit(node);
        if (cycle) return cycle.map((position) => problem.ids[position]);
      }
    }
    return [];
  }

  function reachability(problem, order) {
    const words = (problem.successors.length + 31) >>> 5;
    const reach = problem.successors.map(() => new Uint32Array(words));
    for (let i = order.length - 1; i >= 0; i--) {
      const node = order[i];
      for (const to of problem.successors[node]) {
        reach[node][to >>> 5] |= 1 << (to & 31);
        for (let word = 0; word < words; word++) reach[node][word] |= reach[to][word];
      }
    }
    return reach;
  }

  function hasPath(problem, reach, from, to) {
    for (const u of from) {
      const bits = reach[problem.position.get(u)];
      for (const v of to) {
        const target = problem.position.get(v);
        if (bits[target >>> 5] & (1 << (target & 31))) return true;
      }
    }
    return false;
  }

  /** Tarjan's algorithm. Components come back in topological order. */
  function stronglyConnectedComponents(successors) {
    const count = successors.length;
    const index = new Array(count).fill(-1);
    const low = new Array(count).fill(0);
    const onStack = new Array(count).fill(false);
    const stack = [];
    const components = [];
    let next = 0;
    const visit = (node) => {
      index[node] = low[node] = next++;
      stack.push(node);
      onStack[node] = true;
      for (const to of successors[node]) {
        if (index[to] < 0) {
          visit(to);
          low[node] = Math.min(low[node], low[to]);
        } else if (onStack[to]) {
          low[node] = Math.min(low[node], index[to]);
        }
      }
      if (low[node] === index[node]) {
        const component = [];
        let member;
        do {
          member = stack.pop();
          onStack[member] = false;
          component.push(member);
        } while (member !== node);
        components.push(component);
      }
    };
    for (let node = 0; node < count; node++) if (index[node] < 0) visit(node);
    return components.reverse();
  }

  /** The proper acyclic partition of [C] Section 5.3: SCCs with each group held together. */
  function partition(problem, edges) {
    const extended = problem.successors.map((set) => new Set(set));
    const hold = (group) => {
      for (let i = 0; i < group.length; i++) {
        const next = group[(i + 1) % group.length];
        extended[problem.position.get(group[i])].add(problem.position.get(next));
      }
    };
    for (const edge of edges) {
      hold(edge.x);
      hold(edge.y);
    }
    return stronglyConnectedComponents(extended);
  }

  /**
   * Sat of [C]. Returns { ok: true, directions } or { ok: false, conflict }, or
   * { undetermined: true } if the time budget ran out. Simple edges were dropped by the
   * caller, the first step of Sat.
   */
  function sat(problem, deadline) {
    if (Date.now() > deadline) return { undetermined: true };
    const directions = new Map();
    let open = problem.edges;

    // Resolve: a path between the two sides leaves one possible orientation. Repeated,
    // because each orientation adds arcs that can force further edges.
    for (;;) {
      const order = topologicalOrder(problem.successors);
      if (!order) return { ok: false, conflict: { type: "cycle", nodes: findCycle(problem) } };
      const reach = reachability(problem, order);
      const remaining = [];
      let resolved = false;
      for (const edge of open) {
        const forward = hasPath(problem, reach, edge.x, edge.y);
        const backward = hasPath(problem, reach, edge.y, edge.x);
        if (forward && backward) {
          const nodes = [...edge.x, ...edge.y];
          return { ok: false, conflict: { type: "no-orientation", nodes, origin: edge.origin } };
        }
        if (forward || backward) {
          const direction = forward ? 1 : -1;
          orient(problem, edge, direction);
          directions.set(edge.index, direction);
          resolved = true;
        } else {
          remaining.push(edge);
        }
      }
      open = remaining;
      if (!resolved) break;
    }
    if (open.length === 0) return { ok: true, directions };

    // Partition, then solve each part on its own ([C] Lemma 9). An edge between two parts
    // is oriented by their order, which cannot close a cycle.
    const components = partition(problem, open);
    const partOf = new Map();
    components.forEach((component, part) => {
      for (const position of component) partOf.set(problem.ids[position], part);
    });
    const edgesOfPart = new Map();
    for (const edge of open) {
      const partX = partOf.get(edge.x[0]);
      const partY = partOf.get(edge.y[0]);
      if (partX === partY) {
        if (!edgesOfPart.has(partX)) edgesOfPart.set(partX, []);
        edgesOfPart.get(partX).push(edge);
      } else {
        directions.set(edge.index, partX < partY ? 1 : -1);
      }
    }
    const arcs = arcsOf(problem);
    for (const [part, edges] of edgesOfPart) {
      const ids = components[part].map((position) => problem.ids[position]);
      const members = new Set(ids);
      const within = arcs.filter(([from, to]) => members.has(from) && members.has(to));
      const result = branch(makeProblem(ids, within, edges), deadline);
      if (!result.ok) return result;
      for (const [index, direction] of result.directions) directions.set(index, direction);
    }
    return { ok: true, directions };
  }

  /** NDSat of [C]: try both orientations of one edge. */
  function branch(problem, deadline) {
    const [edge, ...rest] = problem.edges;
    for (const direction of [1, -1]) {
      const attempt = copyProblem(problem, rest);
      orient(attempt, edge, direction);
      const result = sat(attempt, deadline);
      if (result.undetermined) return result;
      if (result.ok) {
        result.directions.set(edge.index, direction);
        return result;
      }
    }
    return { ok: false, conflict: { type: "no-orientation", nodes: problem.ids, origin: edge.origin } };
  }

  /** A model is satisfiable iff its disjunctive graph is orientable ([C] Theorem 7). */
  function checkSatisfiability(graph, options = {}) {
    const hard = [];
    graph.edges.forEach((edge, index) => {
      if (edge.x.length > 1 || edge.y.length > 1) hard.push({ ...edge, index });
    });
    const ids = graph.nodes.map((node) => node.index);
    const deadline = Date.now() + (options.budgetMs ?? DEFAULT_BUDGET_MS);
    const result = sat(makeProblem(ids, graph.arcs, hard), deadline);
    if (result.undetermined) return { status: "undetermined" };
    if (!result.ok) return { status: "unsatisfiable", conflict: result.conflict };
    return { status: "satisfiable", directions: result.directions };
  }

  // ---------------------------------------------------------------------------------
  // Structure checks: the warnings and errors of [C] Section 6
  // ---------------------------------------------------------------------------------

  function analyseStructure(model) {
    const errors = [];
    const warnings = [];
    const byId = new Map(model.tasks.map((task) => [task.id, task]));
    const nameOf = (id) => byId.get(id)?.name ?? id;
    const report = (list, code, message, tasks) => list.push({ code, message, tasks });

    for (const task of model.tasks) {
      if (task.danglingLocations > 0) {
        report(errors, "dangling-location",
          `${task.name}: ${task.danglingLocations} location(s) do not point at a loaded product.`, [task.id]);
      }
      if (task.items.length === 0 && !(task.danglingLocations > 0)) {
        report(errors, "no-locations", `${task.name}: no Locations.`, [task.id]);
      }
      if (!(task.duration > 0)) {
        report(errors, "missing-duration", `${task.name}: Duration is missing.`, [task.id]);
      }

      const items = new Set(task.items);
      if (items.size < task.items.length) {
        report(warnings, "repeated-location", `${task.name}: a location is repeated.`, [task.id]);
      }
      if (task.exclusive && task.exclusive !== "None") {
        reportMissingZones(task, task.exclusive, "its Exclusive Constraint");
      }
      if (task.ordering === "<" || task.ordering === ">") {
        for (const item of items) {
          const elevation = model.items[item]?.elevation;
          if (elevation === null || elevation === undefined) {
            report(warnings, "no-elevation",
              `${task.name}: ${model.items[item]?.name ?? item} has no storey Elevation, so the Ordering Constraint skips it.`, [task.id]);
          }
        }
      }

      const sites = new Set([...items].map((item) => model.items[item]?.zones.IfcSite).filter(Boolean));
      if (sites.size > 1) {
        report(warnings, "several-sites", `${task.name}: its locations are under different IfcSite roots.`, [task.id]);
      }
    }

    function reportMissingZones(task, scope, purpose) {
      for (const item of new Set(task.items)) {
        if (model.items[item] && model.items[item].zones[scope] === undefined) {
          report(warnings, "coarser-than-scope",
            `${task.name}: ${model.items[item].name} has no ${scope}, so ${purpose} does not apply to it.`, [task.id]);
        }
      }
    }

    const activityItems = new Map();
    for (const task of model.tasks) {
      for (const item of new Set(task.items)) {
        const key = `${task.name}\u0000${item}`;
        if (activityItems.has(key)) {
          report(warnings, "shared-node",
            `Two ${task.name} tasks share ${model.items[item]?.name ?? item}; the activity runs there once.`,
            [activityItems.get(key), task.id]);
        }
        activityItems.set(key, task.id);
      }
    }

    for (const dependency of model.dependencies) {
      if (dependency.scope === "None") continue;
      const from = byId.get(dependency.from);
      const to = byId.get(dependency.to);
      if (!from || !to) continue;
      const label = `${nameOf(dependency.from)} -> ${nameOf(dependency.to)}`;
      reportMissingZones(from, dependency.scope, `the dependency ${label}`);
      reportMissingZones(to, dependency.scope, `the dependency ${label}`);
      const zonesOf = (task) => new Set(task.items.map((item) => model.items[item]?.zones[dependency.scope]));
      const fromZones = zonesOf(from);
      const shared = [...zonesOf(to)].some((zone) => zone !== undefined && fromZones.has(zone));
      if (!shared) {
        report(warnings, "no-shared-zone",
          `${label}: no ${dependency.scope} is shared, so the dependency has no effect.`, [from.id, to.id]);
      }
    }

    return { errors, warnings };
  }

  /** Loops in the diagram. A loop can be satisfiable, so it is only ever a warning. */
  function diagramLoops(model) {
    const position = new Map(model.tasks.map((task, index) => [task.id, index]));
    const successors = model.tasks.map(() => new Set());
    for (const dependency of model.dependencies) {
      if (position.has(dependency.from) && position.has(dependency.to)) {
        successors[position.get(dependency.from)].add(position.get(dependency.to));
      }
    }
    return stronglyConnectedComponents(successors)
      .filter((component) => component.length > 1)
      .map((component) => component.map((index) => model.tasks[index].id));
  }

  /**
   * Check Satisfiability. Execution is left out of the first pass because [E] Section 3.2
   * has the modeler "plan or record a specific path": it picks an execution rather than
   * constraining the model. The second pass reports a path that contradicts the
   * constraints as exactly that.
   */
  function checkModel(model, options = {}) {
    const { errors, warnings } = analyseStructure(model);
    const verdict = checkSatisfiability(buildGraph(model), options);
    const graph = buildGraph(model, { execution: true });
    let execution;
    if (verdict.status === "satisfiable" && model.executions.length > 0) {
      execution = checkSatisfiability(graph, options);
    }
    if (verdict.status === "satisfiable") {
      for (const loop of diagramLoops(model)) {
        const names = loop.map((id) => model.tasks.find((task) => task.id === id).name);
        warnings.push({
          code: "satisfiable-loop",
          message: `Loop between ${names.join(", ")}: satisfiable, but a constraint may be redundant.`,
          tasks: loop,
        });
      }
    }
    return { errors, warnings, verdict, execution, graph };
  }

  // ---------------------------------------------------------------------------------
  // Schedule and critical path: [T] Section 6.2
  // ---------------------------------------------------------------------------------

  /**
   * Forward and backward pass on a fully oriented graph, the activity network of
   * [T] p. 58. Returns undefined if the orientation is cyclic.
   */
  function timeNetwork(graph, directions) {
    const count = graph.nodes.length;
    const successors = graph.nodes.map(() => new Set());
    for (const [from, to] of graph.arcs) successors[from].add(to);
    graph.edges.forEach((edge, index) => {
      const [from, to] = directions[index] > 0 ? [edge.x, edge.y] : [edge.y, edge.x];
      for (const u of from) for (const v of to) successors[u].add(v);
    });

    const order = topologicalOrder(successors);
    if (!order) return undefined;

    const duration = graph.nodes.map((node) => node.duration);
    const start = new Array(count).fill(0);
    const finish = new Array(count).fill(0);
    for (const node of order) {
      finish[node] = start[node] + duration[node];
      for (const to of successors[node]) start[to] = Math.max(start[to], finish[node]);
    }
    const projectLength = finish.reduce((longest, value) => Math.max(longest, value), 0);

    const lateFinish = new Array(count).fill(projectLength);
    const lateStart = new Array(count).fill(0);
    const freeFloat = new Array(count).fill(0);
    for (let i = order.length - 1; i >= 0; i--) {
      const node = order[i];
      let earliestSuccessor = projectLength;
      for (const to of successors[node]) {
        lateFinish[node] = Math.min(lateFinish[node], lateStart[to]);
        earliestSuccessor = Math.min(earliestSuccessor, start[to]);
      }
      lateStart[node] = lateFinish[node] - duration[node];
      freeFloat[node] = earliestSuccessor - finish[node];
    }
    const totalFloat = lateStart.map((value, node) => value - start[node]);
    return { start, finish, lateStart, lateFinish, totalFloat, freeFloat, projectLength };
  }

  /**
   * Orients every edge left open by satisfiability. Sat leaves simple edges out, and these
   * can be oriented along any topological order ([C] Lemma 8), so nodes are placed one at
   * a time, earliest possible start first and longest remaining work on ties. Placement
   * order then decides each simple edge, so no cycle can arise.
   */
  function completeOrientation(graph, satDirections) {
    const count = graph.nodes.length;
    const directions = graph.edges.map((_, index) => satDirections.get(index) ?? 0);
    const successors = graph.nodes.map(() => new Set());
    const predecessors = graph.nodes.map(() => new Set());
    const addFixed = (from, to) => {
      successors[from].add(to);
      predecessors[to].add(from);
    };
    for (const [from, to] of graph.arcs) addFixed(from, to);
    const rivals = graph.nodes.map(() => []);
    graph.edges.forEach((edge, index) => {
      if (directions[index] === 0) {
        rivals[edge.x[0]].push({ other: edge.y[0], index, isX: true });
        rivals[edge.y[0]].push({ other: edge.x[0], index, isX: false });
        return;
      }
      const [from, to] = directions[index] > 0 ? [edge.x, edge.y] : [edge.y, edge.x];
      for (const u of from) for (const v of to) addFixed(u, v);
    });

    const order = topologicalOrder(successors);
    const tail = new Array(count).fill(0);
    for (let i = order.length - 1; i >= 0; i--) {
      const node = order[i];
      let longest = 0;
      for (const to of successors[node]) longest = Math.max(longest, tail[to]);
      tail[node] = longest + graph.nodes[node].duration;
    }

    const finish = new Array(count).fill(-1);
    const waiting = predecessors.map((set) => set.size);
    const ready = new Set();
    waiting.forEach((value, node) => {
      if (value === 0) ready.add(node);
    });
    const earliestStart = (node) => {
      let earliest = 0;
      for (const from of predecessors[node]) earliest = Math.max(earliest, finish[from]);
      for (const { other } of rivals[node]) earliest = Math.max(earliest, finish[other]);
      return earliest;
    };
    while (ready.size > 0) {
      let chosen = -1;
      let chosenStart = Infinity;
      for (const node of ready) {
        const start = earliestStart(node);
        if (
          start < chosenStart - EPSILON ||
          (Math.abs(start - chosenStart) < EPSILON && tail[node] > tail[chosen])
        ) {
          chosen = node;
          chosenStart = start;
        }
      }
      ready.delete(chosen);
      finish[chosen] = chosenStart + graph.nodes[chosen].duration;
      // An edge still open means its other node is unplaced, so this node goes first.
      for (const { index, isX } of rivals[chosen]) {
        if (directions[index] === 0) directions[index] = isX ? 1 : -1;
      }
      for (const to of successors[chosen]) {
        waiting[to]--;
        if (waiting[to] === 0) ready.add(to);
      }
    }
    return directions;
  }

  /** Edges with an arc on a critical path; only these can shorten it ([T] p. 59). */
  function criticalEdges(graph, directions, timing) {
    const isCritical = (node) => Math.abs(timing.totalFloat[node]) < EPSILON;
    const candidates = [];
    graph.edges.forEach((edge, index) => {
      const [from, to] = directions[index] > 0 ? [edge.x, edge.y] : [edge.y, edge.x];
      const critical = from.some((u) =>
        isCritical(u) &&
        to.some((v) => isCritical(v) && Math.abs(timing.finish[u] - timing.start[v]) < EPSILON));
      if (critical) candidates.push(index);
    });
    return candidates;
  }

  /**
   * Local search of [T] p. 59: reverse a disjunctive edge on the critical path while the
   * project gets shorter. A reversal can close a cycle here, unlike in a job shop, so
   * those are rejected. An optimal schedule is NP-complete ([T] Section 6.3).
   */
  function shortenByReversal(graph, directions) {
    let timing = timeNetwork(graph, directions);
    let tries = 0;
    let reversals = 0;
    let improved = true;
    while (improved && tries < MAX_REVERSAL_TRIES) {
      improved = false;
      for (const index of criticalEdges(graph, directions, timing)) {
        if (tries >= MAX_REVERSAL_TRIES) break;
        tries++;
        directions[index] = -directions[index];
        const candidate = timeNetwork(graph, directions);
        if (candidate && candidate.projectLength < timing.projectLength - EPSILON) {
          timing = candidate;
          reversals++;
          improved = true;
          break;
        }
        directions[index] = -directions[index];
      }
    }
    return { timing, reversals };
  }

  /** Per-task values, named after IfcTaskTime. Floats take the tightest node. */
  function taskTimes(graph, timing) {
    const times = new Map();
    for (const [task, nodes] of graph.nodesOfTask) {
      if (nodes.length === 0) continue;
      const pick = (values, choose) => choose(...nodes.map((node) => values[node]));
      times.set(task, {
        earlyStart: pick(timing.start, Math.min),
        earlyFinish: pick(timing.finish, Math.max),
        lateStart: pick(timing.lateStart, Math.min),
        lateFinish: pick(timing.lateFinish, Math.max),
        totalFloat: pick(timing.totalFloat, Math.min),
        freeFloat: pick(timing.freeFloat, Math.min),
        isCritical: nodes.some((node) => Math.abs(timing.totalFloat[node]) < EPSILON),
      });
    }
    return times;
  }

  /** Workers are reported, not levelled: Workers is the size of the task's one crew. */
  function peakWorkers(model, graph, timing) {
    const byId = new Map(model.tasks.map((task) => [task.id, task]));
    const events = new Map();
    graph.nodes.forEach((node, index) => {
      const task = byId.get(node.tasks[0]);
      if (!events.has(task.actor)) events.set(task.actor, []);
      events.get(task.actor).push({ at: timing.start[index], change: task.workers });
      events.get(task.actor).push({ at: timing.finish[index], change: -task.workers });
    });
    const peaks = [];
    for (const [actor, changes] of events) {
      changes.sort((a, b) => a.at - b.at || a.change - b.change);
      let current = 0;
      let peak = { actor, workers: 0, at: 0 };
      for (const { at, change } of changes) {
        current += change;
        if (current > peak.workers) peak = { actor, workers: current, at };
      }
      peaks.push(peak);
    }
    return peaks;
  }

  /**
   * Schedule and Critical Path ([T] Section 6.2): find an acyclic orientation, label nodes
   * with durations, and run CPM on the resulting network. The result satisfies the model
   * by construction, but it is not guaranteed to be the shortest.
   */
  function computeSchedule(model, options = {}) {
    const graph = buildGraph(model, { execution: true, scheduleEdges: true });
    const verdict = checkSatisfiability(graph, options);
    if (verdict.status !== "satisfiable") return { status: verdict.status, conflict: verdict.conflict, graph };

    const directions = completeOrientation(graph, verdict.directions);
    const { timing, reversals } = shortenByReversal(graph, directions);
    const nodes = graph.nodes.map((node, index) => ({
      activity: node.activity,
      item: node.item,
      tasks: node.tasks,
      start: timing.start[index],
      finish: timing.finish[index],
      lateStart: timing.lateStart[index],
      lateFinish: timing.lateFinish[index],
      totalFloat: timing.totalFloat[index],
      freeFloat: timing.freeFloat[index],
    }));
    return {
      status: "scheduled",
      graph,
      nodes,
      tasks: taskTimes(graph, timing),
      projectLength: timing.projectLength,
      peaks: peakWorkers(model, graph, timing),
      reversals,
    };
  }

  return {
    buildGraph,
    checkSatisfiability,
    analyseStructure,
    diagramLoops,
    checkModel,
    computeSchedule,
  };
}

