  // Shared by the Flow procedures. Inlined by the generator, so it stays plain statements.
const CLASS_LEVEL = {
  "af3eb87e-0095-5cdf-9cff-acd7ee57e47b": "IfcSite",
  "8d7e3b5a-4837-54c7-a292-d70b911e6b86": "IfcBuilding",
