const parentOf = async (uuid) => {
  for (const relationClass of ["301698e6-9731-52a7-bde9-38186d9a1bc1", "1e2faabe-2c1c-558a-957b-a03791588e72"]) {
    const incoming = await expression.getIncomingRelationsByInstanceUUID(uuid, relationClass);
    if (incoming.length > 0) return expression.getSourceByRelInstanceUUID(incoming[0].uuid);
  }
  return undefined;
};

/** An item with its projection Πs: the zone it falls in at each level of the hierarchy. */
const readItem = async (instance) => {
  const zones = {};
  const path = [];
  let elevation = null;
  let current = instance;
  // The guard is for a hierarchy drawn in a loop, which the metamodel cannot forbid.
  while (current && !path.includes(current.uuid)) {
    path.push(current.uuid);
    const level = CLASS_LEVEL[current.uuid_class];
    if (level) zones[level] = current.uuid;
    if (level === "IfcBuildingStorey" && elevation === null) {
      const value = parseFloat(await expression.attrvalByInst("1e390bc2-23b2-51c2-a0ea-497327183106", current.uuid));
      if (Number.isFinite(value)) elevation = value;
    }
    current = await parentOf(current.uuid);
  }
  const name = (await expression.attrvalByInst("d6632c72-89fa-4210-9d01-18e911505608", instance.uuid)) ?? instance.name;
  return { id: instance.uuid, name, path, zones, elevation };
};

const readRelations = async (relationClass) => {
  const ends = [];
  for (const relation of await expression.getClassInstancesByMetaUUID(relationClass)) {
    const from = await expression.getSourceByRelInstanceUUID(relation.uuid);
    const to = await expression.getDestinationByRelInstanceUUID(relation.uuid);
    if (from && to) ends.push({ relation, from: from.uuid, to: to.uuid });
  }
  return ends;
};

const readScoped = async (relationClass, kind) => {
  const dependencies = [];
  for (const { relation, from, to } of await readRelations(relationClass)) {
    const scope = (await expression.attrvalByInst("2af0633d-cdc8-54ce-a1c4-44eb379e7b81", relation.uuid)) || "None";
    dependencies.push({ kind, from, to, scope });
  }
  return dependencies;
};

const readFlowModel = async () => {
  await expression.loadAllSceneInstances();
  const items = {};
  const tasks = [];
  for (const instance of await expression.getClassInstancesByMetaUUID("70a01e20-d79d-5ddc-a4a6-7a0f66fcdd34")) {
    const text = async (attribute) => (await expression.attrvalByInst(attribute, instance.uuid)) ?? "";
    const table = await expression.getAttrByInstanceUUID(instance.uuid, "0c032743-7eac-5885-b39f-ecc41deb7084");
    const locations = [];
    let danglingLocations = 0;
    for (const cell of [...(table?.table_attributes ?? [])].sort((a, b) => a.table_row - b.table_row)) {
      const target = cell.role_instance_from?.uuid_has_reference_class_instance;
      // A row nobody filled in yet, as every new task's first row is, is no location.
      if (!target) continue;
      const product = await expression.getInstanceByUUID(target);
      if (!product) {
        danglingLocations++;
        continue;
      }
      items[product.uuid] ??= await readItem(product);
      locations.push(product.uuid);
    }
    const ordering = (await text("fb11ac47-ffcc-5720-9c4a-bab44420693b")).trim().charAt(0);
    tasks.push({
      id: instance.uuid,
      name: (await text("d6632c72-89fa-4210-9d01-18e911505608")) || instance.name,
      duration: parseFloat(await text("93dbfdaf-a94a-5d54-9c77-2709ed4a894d")),
      workers: parseFloat(await text("5bc66805-979a-5786-bf8c-11dd611eb81d")) || 0,
      actor: (await text("3f41db90-a9eb-5f30-a1cd-d94df23f41d1")) || "Other",
      ordering: ordering === "<" || ordering === ">" ? ordering : "None",
      exclusive: (await text("15a9c71a-b08f-5874-96bc-9af02add1a5d")) || "None",
      items: locations,
      danglingLocations,
    });
  }
  const executions = (await readRelations("339f5c3f-df5e-5fa9-81b6-cdb292fcb11f")).map(({ from, to }) => ({ from, to }));
  const dependencies = [
    ...(await readScoped("cecf5151-b094-5200-880d-b6423221a110", "precedence")),
    ...(await readScoped("5ec52c21-c159-55b5-9d8b-fbe7753dabb9", "alternate")),
    ...(await readScoped("d972491f-b128-5872-be6b-9ee19b83e261", "chain")),
  ];
  return { items, tasks, dependencies, executions };
};

/** Writes values onto a task, then redraws it once. */
const writeTask = async (task, values) => {
  let last;
  for (const [attribute, value] of values) {
    await expression.setAttrvalByInstanceUUID(task.id, attribute, value);
    last = attribute;
  }
  if (last) await expression.checkForVisualizationUpdateByAttributeUUID(task.id, last);
};

/**
 * What a procedure reports goes to the log as it happens, and into one alert at the end.
 * There is no alert outside a browser, so the tests under Node only log.
 */
const reported = [];
const report = (message, status) => {
  expression.log(message, status);
  reported.push(message);
};
const showReport = (title) => {
  if (reported.length > 0 && typeof globalThis.alert === "function") {
    globalThis.alert(`${title}\n\n${reported.join("\n")}`);
  }
};

/** Saving validates values against the attribute type, whose pattern is ASCII only. */
const asValue = (text) => text.replace(/[^\x20-\x7E]/g, "?").slice(0, 200);

const nodeLabel = (model, node) => `${node.activity} @ ${model.items[node.item]?.name ?? node.item}`;

/** A readable reason, and the tasks to mark, for an unsatisfiable graph. */
const describeConflict = (model, graph, conflict) => {
  const nodes = [...new Set(conflict.nodes)].map((index) => graph.nodes[index]);
  const tasks = [...new Set(nodes.flatMap((node) => node.tasks))];
  const labels = nodes.slice(0, 12).map((node) => nodeLabel(model, node)).join(", ");
  const more = nodes.length > 12 ? ` and ${nodes.length - 12} more` : "";
  const reason = conflict.type === "cycle"
    ? "these must each finish before the next, in a cycle"
    : "no order of these satisfies the exclusive, chain and alternate constraints between them";
  return { tasks, message: `${labels}${more}: ${reason}.` };
};


  const clearResults = async (model) => {
    for (const task of model.tasks) await writeTask(task, COMPUTED_ATTRIBUTES.map((attribute) => [attribute, ""]));
  };

  const run = async () => {
    const core = createCopmodlCore();
    const model = await readFlowModel();
    if (model.tasks.length === 0) {
      report("Schedule and Critical Path: this scene has no IfcTask.", "close");
      return;
    }

    const { errors } = core.analyseStructure(model);
    if (errors.length > 0) {
      for (const error of errors) report(`Structure error. ${error.message}`, "error");
      report("Schedule and Critical Path: fix the structure errors first.", "error");
      await clearResults(model);
      return;
    }

    const schedule = core.computeSchedule(model);
    if (schedule.status !== "scheduled") {
      const reason = schedule.status === "undetermined"
        ? "the time budget ran out before satisfiability was decided"
        : describeConflict(model, schedule.graph, schedule.conflict).message;
      report(`Schedule and Critical Path: no schedule, because ${reason}`, "error");
      await clearResults(model);
      return;
    }

    const round = (value) => String(Math.round(value * 100) / 100);
    for (const task of model.tasks) {
      const times = schedule.tasks.get(task.id);
      await writeTask(task, [
        ["68111cb2-29d1-557e-85ed-93c17ce71aa6", round(times.earlyStart)],
        ["37218a06-9b58-5545-a0e5-d2411c508c1a", round(times.earlyFinish)],
        ["b737aacc-37f0-551d-be47-922143ef76aa", round(times.lateStart)],
        ["1c02b864-26fd-5f6d-8d4c-e0f8e9c530ea", round(times.lateFinish)],
        ["5c517dad-8572-5c07-9ba8-bf3eefc632ee", round(times.freeFloat)],
        ["80b2bfe0-ec30-5bf8-a61a-0bdfd76a26c7", round(times.totalFloat)],
        ["d34821a9-5569-5f18-bb33-37cadb48237b", times.isCritical ? "true" : "false"],
      ]);
    }

    const inOrder = [...schedule.nodes].sort((a, b) => a.start - b.start || a.finish - b.finish);
    for (const node of inOrder) {
      report(`Day ${round(node.start)} to ${round(node.finish)}: ${nodeLabel(model, node)}`, "info");
    }
    for (const peak of schedule.peaks) {
      report(`Peak workers, ${peak.actor}: ${peak.workers} on day ${round(peak.at)}`, "info");
    }
    const critical = model.tasks.filter((task) => schedule.tasks.get(task.id).isCritical).map((task) => task.name);
    report(`Critical tasks: ${critical.join(", ")}`, "info");
    report(`Project length: ${round(schedule.projectLength)} days. Valid, but not guaranteed to be the shortest.`, "done");
  };

  try {
    await run();
  } finally {
    showReport("Schedule and Critical Path");
  }
}
